// Detect creative fatigue from the Meta daily ad-insights the Facebook node
// fetched. Pure data transform: no API calls. For each ad that spent yesterday,
// compare its latest-day CTR to its own average CTR across the prior days it
// actually ran, and flag drops. Builds the Slack report text.
const cfg = $('Config').first().json;
const warnPct = cfg.warnPct ?? 0.3;
const watchPct = cfg.watchPct ?? 0.2;
const minImpr = cfg.minImpr ?? 200;
const minSpend = cfg.minSpend ?? 20;
const minShowDrop = cfg.minShowDrop ?? 0.1;

const rows = $input.first().json.data || [];

let latestDate = '';
for (const r of rows) { const d = r.date_stop || r.date_start; if (d > latestDate) latestDate = d; }

const byAd = {};
for (const r of rows) {
  const key = r.ad_id;
  (byAd[key] = byAd[key] || { name: r.ad_name, adset: r.adset_name || '', campaign: r.campaign_name || '', days: [] }).days.push({
    date: r.date_stop || r.date_start,
    ctr: parseFloat(r.ctr) || 0,
    spend: parseFloat(r.spend) || 0,
    impressions: parseInt(r.impressions, 10) || 0,
  });
}

const cutoff7 = (() => { const d = new Date(latestDate); d.setDate(d.getDate() - 6); return d.toISOString().slice(0, 10); })();
const ads = [];
for (const a of Object.values(byAd)) {
  const latest = a.days.find((d) => d.date === latestDate);
  if (!latest || latest.spend < minSpend) continue;
  const spend7 = a.days.filter((d) => d.date >= cutoff7).reduce((s, d) => s + d.spend, 0);
  const prior = a.days
    .filter((d) => d.date !== latestDate && d.impressions >= minImpr && d.spend >= minSpend)
    .sort((x, y) => new Date(x.date) - new Date(y.date));
  let avgCtr = null, drop = null;
  if (prior.length >= 2) {
    avgCtr = prior.reduce((s, d) => s + d.ctr, 0) / prior.length;
    if (avgCtr > 0) drop = (avgCtr - latest.ctr) / avgCtr;
  }
  ads.push({ name: a.name, adset: a.adset, campaign: a.campaign, latestCtr: latest.ctr, avgCtr, spend: latest.spend, spend7, drop });
}

const statusOf = (d) => (d == null ? 'NEW' : d >= warnPct ? 'WARN' : d >= watchPct ? 'WATCH' : 'OK');
let warn = 0, watch = 0, ok = 0, fresh = 0;
for (const a of ads) { const s = statusOf(a.drop); if (s === 'WARN') warn++; else if (s === 'WATCH') watch++; else if (s === 'NEW') fresh++; else ok++; }

const lpad = (s, n) => String(s).padStart(n);
const rpad = (s, n) => String(s).padEnd(n);
const clip = (s, n) => (s.length > n ? s.slice(0, n - 1) + '.' : s);
const pct = (v) => (v == null ? '-' : (v * 100).toFixed(0) + '%');
const ctr = (v) => (v == null ? '-' : v.toFixed(2) + '%');

const shown = ads.filter((a) => a.drop != null && a.drop >= minShowDrop).sort((x, y) => y.drop - x.drop);
let table = '     ' + lpad('Down', 5) + '  ' + lpad('CTR', 6) + '  ' + lpad('Avg', 6) + '  ' + lpad('Yday', 6) + '  ' + lpad('7d', 7) + '  ' + rpad('Campaign', 18) + '  ' + rpad('Ad set', 18) + '  Ad\n';
if (!shown.length) {
  table += '(no ads down at least ' + Math.round(minShowDrop * 100) + '% among yesterday spenders)\n';
} else {
  for (const a of shown) {
    table += rpad(statusOf(a.drop), 5) + ' '
      + lpad(pct(a.drop), 5) + '  '
      + lpad(ctr(a.latestCtr), 6) + '  '
      + lpad(ctr(a.avgCtr), 6) + '  '
      + lpad('$' + a.spend.toFixed(0), 6) + '  '
      + lpad('$' + a.spend7.toFixed(0), 7) + '  '
      + rpad(clip(a.campaign, 18), 18) + '  '
      + rpad(clip(a.adset, 18), 18) + '  '
      + clip(a.name, 28) + '\n';
  }
}

const date = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
const bt = '```';
const parts = [warn + ' need action', watch + ' keep an eye', ok + ' healthy'];
if (fresh) parts.push(fresh + ' new (no baseline)');
const message =
  '*Creative Fatigue - Daily Report* (' + date + ')\n' +
  '_ads that spent yesterday (>= $' + minSpend + '), CTR down >= ' + Math.round(minShowDrop * 100) + '% vs the ad own running-day average_\n' +
  bt + '\n' + table + bt + '\n' +
  '*Summary:* ' + ads.length + ' ads spent yesterday - ' + parts.join(' - ') + '.\n' +
  '_Legend: WARN down >= ' + Math.round(warnPct * 100) + '%, WATCH ' + Math.round(watchPct * 100) + '-' + Math.round(warnPct * 100) + '%, OK < ' + Math.round(watchPct * 100) + '%, NEW not enough history._';

return [{ json: { message, warn, watch, ok, fresh, total: ads.length } }];
